#!/usr/bin/env bash
# Some portions generated by Codex. Run only after explicit shared-machine handoff.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../../.." && pwd)
cd "$ROOT"
D=experiments/overlay/workbench-e2e
# Correctness precedes timing; do not pool this smaller-window validation time.
python3 "$D/run.py" lifetime on pr-current-exact --size 100 --validate
# Mirror order controls drift; hash is a separately frozen API, not the earlier prototype.
python3 "$D/run.py" lifetime off life-e-off --size 1000000
python3 "$D/run.py" lifetime on life-f-on --size 1000000
python3 "$D/run.py" combined_hash on hash-g-on --size 1000000
python3 "$D/run.py" combined_hash on hash-h-on --size 1000000
